1	@use "../abstract" as *;
2	
3	// =============================================================================
4	// Masking text — base structure only.
5	// State transitions (data-reveal, data-mask) live in state/_reveal-state.scss
6	// so TS-driven dynamic state is isolated in a dedicated cascade layer.
7	// =============================================================================
8	
9	@mixin text-reveal-line-hidden {
10	  transform: translate3d(0, var(--text-reveal-offset-y), 0);
11	  opacity: 0;
12	  filter: blur(var(--text-reveal-blur));
13	}
14	
15	@mixin text-reveal-line-visible {
16	  transform: translate3d(0, 0, 0);
17	  opacity: 1;
18	  filter: blur(0);
19	}
20	
21	@mixin text-reveal-line-down {
22	  transform: translate3d(0, var(--text-reveal-down-offset-y), 0);
23	  opacity: 0;
24	  filter: blur(var(--text-reveal-down-blur));
25	}
26	
27	// Base: mask-target is hidden until TS sets data-mask="ready".
28	.mask-target {
29	  opacity: 0;
30	  visibility: hidden;
31	}
32	
33	// Global opt-out on <html> — pins everything to the hidden state, no transitions.
34	.is-text-reveal-disabled {
35	  .mask-target {
36	    opacity: 0;
37	    visibility: hidden;
38	  }
39	
40	  .masking-text {
41	    opacity: 0;
42	    visibility: hidden;
43	
44	    .masking-text__line,
45	    .line {
46	      @include text-reveal-line-hidden();
47	      transition: none;
48	    }
49	  }
50	}
51	
52	.masking-text {
53	  display: block;
54	  overflow: hidden;
55	  opacity: 1;
56	  visibility: visible;
57	  transition:
58	    opacity var(--transition-base),
59	    visibility var(--transition-base);
60	
61	  .masking-text__line,
62	  .line {
63	    display: block;
64	    position: relative;
65	    text-align: start;
66	    @include text-reveal-line-hidden();
67	    transition:
68	      transform var(--transition-slow),
69	      opacity var(--transition-slow),
70	      filter var(--transition-slow);
71	    will-change: transform, opacity, filter;
72	  }
73	}
74	
75	// Multi-line stagger — structural, not state-specific.
76	
77	.masking-text + .masking-text {
78	  .masking-text__line,
79	  .line {
80	    transition-delay: var(--duration-stagger);
81	  }
82	}
83	
84	.masking-text + .masking-text + .masking-text {
85	  .masking-text__line,
86	  .line {
87	    transition-delay: calc(var(--duration-stagger) * 2);
88	  }
89	}
90	
91	.masking-text + .masking-text + .masking-text + .masking-text {
92	  .masking-text__line,
93	  .line {
94	    transition-delay: calc(var(--duration-stagger) * 3);
95	  }
96	}
97	
98	.masking-text + .masking-text + .masking-text + .masking-text + .masking-text {
99	  .masking-text__line,
100	  .line {
101	    transition-delay: calc(var(--duration-stagger) * 4);
102	  }
103	}
