1	@use "../components/masking-text" as mt;
2	
3	// =============================================================================
4	// Reveal state layer — driven by TS via data attributes.
5	// - [data-mask]  : applied to `.mask-target` wrappers
6	// - [data-reveal]: applied to `.masking-text` elements
7	// Values are mutually exclusive per attribute, so adjacent states cannot pile
8	// up the way class-based states used to.
9	// =============================================================================
10	
11	// mask-target wrapper becomes visible when TS finishes wrapping.
12	.mask-target[data-mask="ready"] {
13	  opacity: 1;
14	  visibility: visible;
15	}
16	
17	// Reveal-in: observer or manual trigger sets data-reveal="inview".
18	.masking-text[data-reveal="inview"] {
19	  .masking-text__line,
20	  .line {
21	    @include mt.text-reveal-line-visible();
22	  }
23	}
24	
25	// Reveal-out with downward drop.
26	.masking-text[data-reveal="down"] {
27	  opacity: 1;
28	  visibility: visible;
29	
30	  .masking-text__line,
31	  .line {
32	    @include mt.text-reveal-line-down();
33	    transition-duration: var(--duration-slower);
34	    transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
35	  }
36	}
37	
38	// Explicit hidden — wrapper stays mounted but content is clipped.
39	.masking-text[data-reveal="hidden"] {
40	  opacity: 0;
41	  visibility: hidden;
42	
43	  .masking-text__line,
44	  .line {
45	    @include mt.text-reveal-line-hidden();
46	  }
47	}
